// This implementation assumes the use of a robust geometric library like Boost.Geometry
    // as implementing a general polygon union (handling holes, self-intersections, and 
    // floating point precision) from scratch is a massive undertaking.

    namespace bg = boost::geometry;
    typedef bg::model::polygon<bg::model::d2::point_xy<double>> PolygonType;
    typedef bg::model::multi_polygon<PolygonType> MultiPolygonType;

    // Convert input Polygon2d to Boost.Geometry format
    PolygonType poly1, poly2;
    bg::assign_points(poly1, P1.outer_ring);
    for (const auto& hole : P1.holes) {
        poly1.inners().push_back(hole);
    }
    bg::assign_points(poly2, P2.outer_ring);
    for (const auto& hole : P2.holes) {
        poly2.inners().push_back(hole);
    }

    // Perform the union operation
    MultiPolygonType result_multi;
    bg::union_(poly1, poly2, result_multi);

    // Convert Boost MultiPolygon back to std::vector<PolygonWithHoles2d>
    std::vector<PolygonWithHoles2d> final_polygons;
    for (const auto& poly : result_multi) {
        PolygonWithHoles2d p_out;

        // Extract outer ring
        for (const auto& pt : poly.outer()) {
            p_out.outer_ring.push_back({pt.x(), pt.y()});
        }

        // Extract holes
        for (const auto& inner : poly.inners()) {
            std::vector<Point2d> hole;
            for (const auto& pt : inner) {
                hole.push_back({pt.x(), pt.y()});
            }
            p_out.holes.push_back(hole);
        }

        final_polygons.push_back(p_out);
    }

    return final_polygons;
// END_CODE

